"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * List — a composable list of rows: leading icon/avatar, title, optional
 * description, trailing content. Distinct from `Table` (tabular data): List
 * is single-column, built for mobile menus, settings screens and search
 * results.
 */
const List = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} role="list" className={cn("flex flex-col divide-y divide-border", className)} {...props} />
  ),
);
List.displayName = "List";

export interface ListItemProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  leading?: React.ReactNode;
  title: React.ReactNode;
  description?: React.ReactNode;
  trailing?: React.ReactNode;
  disabled?: boolean;
  /** render as a pressable row */
  onSelect?: () => void;
}

const ListItem = React.forwardRef<HTMLDivElement, ListItemProps>(
  ({ className, leading, title, description, trailing, disabled, onSelect, ...props }, ref) => {
    const interactive = !!onSelect && !disabled;
    const rowClass = cn(
      "flex items-center gap-3 px-3 py-3 font-sans outline-none",
      // ring keeps the highlighted row perceptible where the accent fill is <3:1 (dark)
      interactive &&
        "cursor-pointer hover:bg-accent hover:ring-1 hover:ring-inset hover:ring-ring focus-visible:bg-accent focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-ring",
      disabled && "pointer-events-none opacity-disabled",
      className,
    );
    const content = (
      <>
        {leading && <div className="flex shrink-0 items-center justify-center">{leading}</div>}
        <div className="min-w-0 flex-1">
          <div className="truncate text-body-md text-foreground">{title}</div>
          {description && <div className="truncate text-body-sm text-muted-foreground">{description}</div>}
        </div>
        {trailing && <div className="flex shrink-0 items-center gap-2">{trailing}</div>}
      </>
    );

    if (!interactive) {
      return (
        <div ref={ref} role="listitem" aria-disabled={disabled} className={rowClass} {...props}>
          {content}
        </div>
      );
    }

    // A list's only valid children are listitems, so a pressable row is a listitem that
    // contains the button — not a button standing in for the listitem.
    return (
      <div role="listitem">
        <div
          ref={ref}
          role="button"
          tabIndex={0}
          onClick={onSelect}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              onSelect?.();
            }
          }}
          className={rowClass}
          {...props}
        >
          {content}
        </div>
      </div>
    );
  },
);
ListItem.displayName = "ListItem";

export { List, ListItem };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
